-- SPEC-005 review fix (2026-11-11): relay a record's events in write order, per workspace.
-- relay_seq is taken when the event row is inserted, after the change holds the record's row lock,
-- so it orders every write of one record, also across a delete and a re-import of the same legacy id
-- (the record version restarts at 1 there). Append-only: do not edit once applied.

ALTER TABLE cash_flow.outbox ADD COLUMN relay_seq bigint GENERATED BY DEFAULT AS IDENTITY;

-- Rows written before this migration keep the order the relay used until now. The migrator has no
-- BYPASSRLS and the outbox forces RLS, so lift the force for the backfill (as 0003 does) or the
-- UPDATE and max() see no workspace's rows.
ALTER TABLE cash_flow.outbox NO FORCE ROW LEVEL SECURITY;
UPDATE cash_flow.outbox o SET relay_seq = n.seq
FROM (
    SELECT id, row_number() OVER (
        ORDER BY subject, coalesce((payload->>'version')::bigint, 0), occurred_at, id
    ) AS seq
    FROM cash_flow.outbox
) n
WHERE o.id = n.id;
SELECT setval(pg_get_serial_sequence('cash_flow.outbox', 'relay_seq'),
              coalesce((SELECT max(relay_seq) FROM cash_flow.outbox), 0) + 1, false);
ALTER TABLE cash_flow.outbox FORCE ROW LEVEL SECURITY;
ALTER TABLE cash_flow.outbox ALTER COLUMN relay_seq SET NOT NULL;

DROP INDEX cash_flow.outbox_unrelayed;
CREATE INDEX outbox_unrelayed ON cash_flow.outbox (relay_seq) WHERE relayed_at IS NULL;
